import type { Metadata } from "next";
import Image from "next/image";
import Link from "next/link";
import { ExternalLink } from "lucide-react";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { logout } from "@/app/actions/auth";
import { AdminNav } from "@/components/admin/AdminNav";

export const metadata: Metadata = { title: { default: "Admin", template: "%s · Admin | Sun Metals Store" }, robots: { index: false, follow: false } };

// The admin is always per-request and per-user; it opts out of instant-navigation validation.
export const instant = false;

export default async function AdminLayout({ children }: LayoutProps<"/admin">) {
  const user = await requireAdmin();
  const [newLeads, toShip] = await Promise.all([
    db.lead.count({ where: { status: "NEW" } }),
    db.order.count({ where: { status: { in: ["PAID", "PROCESSING"] } } }),
  ]);
  return (
    <div className="flex min-h-screen flex-col bg-[#f4f3f0] lg:flex-row">
      <aside className="bg-ink p-3 text-white lg:sticky lg:top-0 lg:h-screen lg:w-60 lg:shrink-0 lg:overflow-y-auto lg:p-4">
        <Link href="/admin" className="mb-4 hidden items-center gap-2 lg:flex">
          <Image src="/logo.png" alt="" width={36} height={36} className="rounded-full bg-white" />
          <span className="font-display text-lg font-bold leading-none">Sun Metals<span className="block text-[10px] font-normal tracking-widest text-brass-light">ADMIN</span></span>
        </Link>
        <AdminNav newLeads={newLeads} toShip={toShip} />
        <div className="mt-6 hidden border-t border-white/10 pt-4 text-xs text-white/60 lg:block">
          <p className="font-semibold text-white">{user.name}</p>
          <p>{user.role === "ADMIN" ? "Owner" : "Staff"}</p>
          <Link href="/" className="mt-3 flex items-center gap-1 hover:text-white">View store <ExternalLink className="h-3 w-3" /></Link>
          <form action={logout}><button className="mt-2 hover:text-white">Sign out</button></form>
        </div>
      </aside>
      <main className="min-w-0 flex-1 p-4 sm:p-6 lg:p-8">{children}</main>
    </div>
  );
}
